        }
      ]
    },
    {
      "id": "F-9",
      "claim": "The retained discovery read of vault note 'Engineering Notes/loanflow-integer-input-convention.md' (LFCONV-INTGUARD-01, content_sha256 ce8d5eacd9f42054685517532707ad85c3ad2f139f5c91c57b8e102474bb6334) says three things: the guard is `isinstance(value, bool) or not isinstance(value, int)`, the guard raises ValidationError, and the guard runs before range checks. It also names Money, Percentage and classify_credit_score as the existing locations. This is historical metadata only.",
      "classification": "found",
      "evidence": [
        {
          "path": "runs/run-20261002-obsidianlive-004/obsidian/read/read-3.json",
          "start_line": 18,
          "end_line": 21,
          "evidence_tier": "metadata"
