      "id": "F-10",
      "claim": "Business(business_id='BZ-1', legal_name='Acme', years_in_operation=3.5) currently constructs without error, and so does years_in_operation=True.",
      "classification": "inferred",
      "supporting_finding_ids": [
        "F-1"
